// Extract parameters safely from Retell or test payload
const raw = $input.first().json;
const body = raw.body || raw;
const args = body.args || body;

const rawSlot = String(args.desired_slot || args.time || "2:30 PM").trim();
const s = rawSlot.toLowerCase();
const patientName = String(args.patient_name || args.name || "Valued Patient").trim();
let phone = String(args.phone_number || args.phone || "+15550199000").replace(/[^\d+]/g, "");
if (!phone.startsWith("+")) phone = "+1" + phone;
const rawReason = String(args.reason || "General Checkup").toLowerCase();

// SCENARIO 3: HIPAA PHI Sanitization & De-identification
let sanitizedCategory = "General Consultation & Checkup";
if (rawReason.includes("clean") || rawReason.includes("hygiene") || rawReason.includes("plaque")) {
  sanitizedCategory = "Routine Dental Hygiene & Cleaning";
} else if (rawReason.includes("pain") || rawReason.includes("toothache") || rawReason.includes("emergency") || rawReason.includes("broken")) {
  sanitizedCategory = "Priority Diagnostic Triage";
} else if (rawReason.includes("whiten") || rawReason.includes("cosmetic")) {
  sanitizedCategory = "Cosmetic Consultation";
}

// 1. Dynamic Date Resolution in Eastern Time (America/New_York)
const nowNyStr = new Date().toLocaleString("en-US", { timeZone: "America/New_York" });
const nyNow = new Date(nowNyStr);
const pad = (n) => String(n).padStart(2, "0");
let targetDate = new Date(nyNow);

const isoM = s.match(/(\d{4})-(\d{2})-(\d{2})/);
const slashM = s.match(/\b(\d{1,2})\/(\d{1,2})(?:\/(\d{2,4}))?\b/);
const months = { jan: 0, january: 0, feb: 1, february: 1, mar: 2, march: 2, apr: 3, april: 3, may: 4, jun: 5, june: 5, jul: 6, july: 6, aug: 7, august: 7, sep: 8, september: 8, oct: 9, october: 9, nov: 10, november: 10, dec: 11, december: 11 };
const monM = s.match(/\b(jan(?:uary)?|feb(?:ruary)?|mar(?:ch)?|apr(?:il)?|may|june?|july?|aug(?:ust)?|sep(?:tember)?|oct(?:ober)?|nov(?:ember)?|dec(?:ember)?)\s+(\d{1,2})(?:st|nd|rd|th)?\b/i);
const days = { sunday: 0, sun: 0, monday: 1, mon: 1, tuesday: 2, tue: 2, tues: 2, wednesday: 3, wed: 3, thursday: 4, thu: 4, thurs: 4, friday: 5, fri: 5, saturday: 6, sat: 6 };
const dayM = s.match(/\b(sunday|sun|monday|mon|tuesday|tues?|wednesday|wed|thursday|thurs?|friday|fri|saturday|sat)\b/i);

if (isoM) {
  targetDate = new Date(parseInt(isoM[1], 10), parseInt(isoM[2], 10) - 1, parseInt(isoM[3], 10));
} else if (slashM) {
  const yr = slashM[3] ? (slashM[3].length === 2 ? 2000 + parseInt(slashM[3], 10) : parseInt(slashM[3], 10)) : nyNow.getFullYear();
  targetDate = new Date(yr, parseInt(slashM[1], 10) - 1, parseInt(slashM[2], 10));
} else if (monM) {
  const mIdx = months[monM[1].toLowerCase()];
  targetDate = new Date(nyNow.getFullYear(), mIdx, parseInt(monM[2], 10));
  if (targetDate < new Date(nyNow.getFullYear(), nyNow.getMonth(), nyNow.getDate())) {
    targetDate.setFullYear(nyNow.getFullYear() + 1);
  }
} else if (s.includes("tomorrow")) {
  targetDate.setDate(targetDate.getDate() + 1);
} else if (s.includes("today")) {
  // keeps today
} else if (dayM) {
  const targetDow = days[dayM[1].toLowerCase()];
  const curDow = nyNow.getDay();
  let diff = (targetDow - curDow + 7) % 7;
  if (diff === 0 && (s.includes("next") || nyNow.getHours() >= 17)) diff = 7;
  targetDate.setDate(targetDate.getDate() + diff);
} else {
  targetDate.setDate(targetDate.getDate() + 1);
}

const askedWeekend = !!(dayM && (days[dayM[1].toLowerCase()] === 0 || days[dayM[1].toLowerCase()] === 6));
const isClosedWeekend = targetDate.getDay() === 0 || targetDate.getDay() === 6;
if (!askedWeekend && isClosedWeekend) {
  if (targetDate.getDay() === 6) targetDate.setDate(targetDate.getDate() + 2);
  if (targetDate.getDay() === 0) targetDate.setDate(targetDate.getDate() + 1);
}

// Dynamic Eastern Time UTC Offset (-05:00 EST / -04:00 EDT)
const tzParts = new Intl.DateTimeFormat("en-US", { timeZone: "America/New_York", timeZoneName: "shortOffset" }).formatToParts(targetDate);
const tzVal = (tzParts.find((p) => p.type === "timeZoneName") || {}).value || "GMT-5";
const offMatch = tzVal.match(/GMT([+-]\d+)/);
const offHr = offMatch ? parseInt(offMatch[1], 10) : -5;
const tzOffset = (offHr < 0 ? "-" : "+") + pad(Math.abs(offHr)) + ":00";

// 2. Strict Time Parsing & 30-Min Interval Snapping
let hour = 14, minute = 30;
const match = s.match(/(\d{1,2}):(\d{2})\s*(am|pm)?|(\d{1,2})\s*(am|pm)/i);
if (match) {
  let rawMin = 0, ampm = "";
  if (match[1]) {
    hour = parseInt(match[1], 10);
    rawMin = parseInt(match[2], 10);
    ampm = (match[3] || "").toLowerCase();
  } else {
    hour = parseInt(match[4], 10);
    ampm = (match[5] || "").toLowerCase();
  }
  if (ampm === "pm" && hour < 12) hour += 12;
  if (ampm === "am" && hour === 12) hour = 0;
  if (!ampm && hour >= 1 && hour <= 6) hour += 12;

  if (rawMin < 15) minute = 0;
  else if (rawMin < 45) minute = 30;
  else { minute = 0; hour += 1; }
}

// 3. Real-World Collision & Clinic Hours Checks
let conflictReason = null;
if (askedWeekend && isClosedWeekend) {
  conflictReason = "Our dental office is closed on weekends. Would Monday at 10:00 AM or 2:30 PM work instead?";
} else if (hour === 12 || s.includes("noon")) {
  conflictReason = "Dr. Smith is unavailable during lunch from 12:00 PM to 1:00 PM. Would 2:30 PM or 3:30 PM work instead?";
} else if (hour < 9 || hour >= 17) {
  conflictReason = "Our clinic hours are 9:00 AM to 5:00 PM Eastern Time. Would 10:00 AM or 2:30 PM work instead?";
}
const isConflict = Boolean(conflictReason);

const dateStr = `${targetDate.getFullYear()}-${pad(targetDate.getMonth() + 1)}-${pad(targetDate.getDate())}`;
const startTime = `${dateStr}T${pad(hour)}:${pad(minute)}:00${tzOffset}`;
let endMin = minute + 30, endHr = hour;
if (endMin >= 60) { endHr += 1; endMin -= 60; }
const endTime = `${dateStr}T${pad(endHr)}:${pad(endMin)}:00${tzOffset}`;

const dispHr = hour > 12 ? hour - 12 : (hour === 0 ? 12 : hour);
const dispAmPm = hour >= 12 ? "PM" : "AM";
const cleanDateLabel = targetDate.toLocaleDateString("en-US", { weekday: "short", month: "short", day: "numeric" });
const cleanSlotLabel = `${cleanDateLabel} at ${dispHr}:${pad(minute)} ${dispAmPm}`;

return [{
  json: {
    patient_name: patientName,
    phone_number: phone,
    requested_slot: rawSlot,
    sanitized_category: sanitizedCategory,
    is_conflict: isConflict,
    conflict_reason: conflictReason,
    confirmed_slot: isConflict ? null : cleanSlotLabel,
    start_time_iso: startTime,
    end_time_iso: endTime,
    alternate_slots: ["2:30 PM", "3:30 PM"],
    timestamp: new Date().toISOString()
  }
}];
